(function() {
    'use strict';

    class SupplyChainAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Global Supply Chain Resilience';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title: 'The Storm Breaks',
                    briefing: '🚢 <strong>Port of Long Beach closes</strong> due to a prolonged labor strike. All trans-Pacific shipments are halted indefinitely.<br><br>🏭 <strong>ChemBase Ltd.</strong>, your largest Tier-1 supplier (45% of key surfactant input), signals insolvency and may file for bankruptcy within days.<br><br>⚠ Geopolitical intelligence warns of <strong>imminent sanctions</strong> on a specialty polymer imported from Russia, critical for NordaPro production.<br><br>Norda currently holds 14 days of finished goods inventory. You must act now.',
                    eventText: '🚢 Port Closure  •  🏭 Supplier Distress  •  ⚠ Sanctions Warning',
                    portCapacity: 0,
                    supplierHealth: 60,
                    baseDrain: 5000000,
                    recoveryDrain: 50,
                    satisfactionDrain: 8,
                    otifDrain: 15
                },
                {
                    title: 'Triage and Rebalancing',
                    briefing: '🏭 <strong>ChemBase Ltd. has filed for bankruptcy.</strong> Your primary surfactant supply is cut off.<br><br>🚢 Port of Long Beach remains closed with no resolution in sight. Sanctions on the Russian polymer are <strong>officially confirmed</strong>.<br><br>📦 Inventory audit: NordaHome has <strong>8 days</strong> of stock. NordaCare has 22 days. NordaPro has 31 days. Six major customers face stock-outs within 10 days.<br><br>You must prioritize who gets product and activate emergency logistics.',
                    eventText: '📦 Critical Inventory  •  🏭 Supplier Bankrupt  •  ⚠ Sanctions Active',
                    portCapacity: 0,
                    supplierHealth: 20,
                    baseDrain: 5000000,
                    recoveryDrain: 20,
                    satisfactionDrain: 10,
                    otifDrain: 15
                },
                {
                    title: 'Qualification Under Fire',
                    briefing: 'Two alternative surfactant suppliers have been identified:<br><br>🇮🇳 <strong>India (SurfChem Mumbai):</strong> 12-week qualification, competitive pricing, quality certification pending.<br>🇩🇪 <strong>Germany (RheinChem GmbH):</strong> 6-week qualification, 40% higher cost, immediately certified.<br><br>🚢 Port crisis partially resolved: <strong>40% capacity restored</strong> via Oakland and Seattle rerouting. Transit times increased by 8-12 days.<br><br>Your sourcing strategy this round is critical for the recovery trajectory.',
                    eventText: '🌍 Alternative Suppliers Available  •  🚢 40% Port Capacity Restored',
                    portCapacity: 40,
                    supplierHealth: 35,
                    baseDrain: 3000000,
                    recoveryDrain: 5,
                    satisfactionDrain: 3,
                    otifDrain: 8
                },
                {
                    title: 'The Second Wave',
                    briefing: '⚠ <strong>Oakland port develops queue delays</strong> — rerouting proves insufficient for full volume.<br><br>🇮🇳 Indian supplier quality pre-assessment reveals <strong>contamination issues</strong> in the first test batch. A $2.3M quality compromise is on the table with enhanced inspection.<br><br>💰 Your largest retail customer (18% of NordaHome revenue) issues a <strong>formal service-level penalty notice</strong> and is evaluating alternative suppliers.<br><br>Consider reshoring partial production to the Monterrey plant as an emergency measure.',
                    eventText: '⚠ Quality Alert  •  💰 Customer Penalty  •  🚢 Rerouting Delays',
                    portCapacity: 50,
                    supplierHealth: 45,
                    baseDrain: 3000000,
                    recoveryDrain: 10,
                    satisfactionDrain: 8,
                    otifDrain: 8
                },
                {
                    title: 'Stabilization',
                    briefing: '✅ <strong>German supplier RheinChem begins delivering.</strong> Quality meets specifications. Cost premium is significant but supply is reliable.<br><br>✅ Revised NordaPro formula <strong>without the sanctioned polymer</strong> has been approved by regulatory authorities.<br><br>💰 Cash position under severe pressure: <strong>$4.1M</strong> in unplanned expediting costs, <strong>$1.8M</strong> in customer penalties, and <strong>$3.2M</strong> in inventory write-offs from quality holds.<br><br>Financial decisions this round will determine whether Norda can fund the recovery program.',
                    eventText: '✅ Supply Restoring  •  💰 $9.1M Crisis Impact  •  📊 Cash Review',
                    portCapacity: 70,
                    supplierHealth: 65,
                    baseDrain: 1000000,
                    recoveryDrain: 0,
                    satisfactionDrain: 2,
                    otifDrain: 2
                },
                {
                    title: 'Recovery and Redesign',
                    briefing: '🚢 <strong>Port of Long Beach reopens at full capacity.</strong> The operational crisis is contained.<br><br>However, Norda remains structurally exposed in the same ways as before the crisis. The board demands a <strong>resilience roadmap</strong>.<br><br>📊 Your final decisions should focus on <strong>long-term strategic positioning</strong>: supplier diversification targets, strategic buffer stock policy, early-warning monitoring, and crisis playbook documentation.<br><br>The quality of your resilience design will determine the final score.',
                    eventText: '🚢 Port Reopened  •  📊 Resilience Redesign Phase  •  🌍 Strategic Planning',
                    portCapacity: 100,
                    supplierHealth: 80,
                    baseDrain: 1000000,
                    recoveryDrain: 0,
                    satisfactionDrain: 0,
                    otifDrain: 0
                }
            ];

            this.SUPPLIER_EFFECTS = {
                aggressive_diversify: { recoveryBoost: 15, costImpact: 3000000, otifBoost: 5, satBoost: 2 },
                moderate_diversify:   { recoveryBoost: 10, costImpact: 1500000, otifBoost: 3, satBoost: 1 },
                maintain_current:     { recoveryBoost: 2,  costImpact: 200000,  otifBoost: -2, satBoost: -1 },
                cost_minimize:        { recoveryBoost: 0,  costImpact: 0,       otifBoost: -5, satBoost: -3 }
            };

            this.LOGISTICS_EFFECTS = {
                air_freight:      { otifBoost: 8,  costImpact: 4000000, satBoost: 3 },
                mixed_mode:       { otifBoost: 4,  costImpact: 2000000, satBoost: 1 },
                ocean_standard:   { otifBoost: -3, costImpact: 500000,  satBoost: -3 },
                reroute_overland: { otifBoost: 2,  costImpact: 1500000, satBoost: 0 }
            };

            this.ALLOCATION_EFFECTS = {
                strategic_priority: { satBoost: 5,  otifBoost: -2, revenueImpact: -500000 },
                revenue_priority:   { satBoost: -2, otifBoost: 3,  revenueImpact: 1000000 },
                balanced:           { satBoost: 2,  otifBoost: 1,  revenueImpact: 200000 },
                contractual_only:   { satBoost: -1, otifBoost: 0,  revenueImpact: 0 }
            };

            this.FINANCE_EFFECTS = {
                draw_credit:      { cashBoost: 5000000, costImpact: 500000 },
                defer_capex:      { cashBoost: 3000000, costImpact: 0 },
                renegotiate_terms: { cashBoost: 2000000, costImpact: 300000 },
                conservative:     { cashBoost: 0,       costImpact: 0 }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    cash: 50000000,
                    otif: 98,
                    recoveryLevel: 100,
                    customerSatisfaction: 95,
                    totalCrisisCost: 0,
                    otifHistory: [],
                    cashHistory: [],
                    recoveryHistory: [],
                    satisfactionHistory: [],
                    crisisCostHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    supplier: 'moderate_diversify',
                    logistics: 'mixed_mode',
                    allocation: 'balanced',
                    finance: 'conservative'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var supplierInput = document.getElementById('supplierInput');
            var logisticsInput = document.getElementById('logisticsInput');
            var allocationInput = document.getElementById('allocationInput');
            var financeInput = document.getElementById('financeInput');

            if (supplierInput) decisions.supplier = supplierInput.value;
            if (logisticsInput) decisions.logistics = logisticsInput.value;
            if (allocationInput) decisions.allocation = allocationInput.value;
            if (financeInput) decisions.finance = financeInput.value;

            var validSupplier = ['aggressive_diversify', 'moderate_diversify', 'maintain_current', 'cost_minimize'];
            var validLogistics = ['air_freight', 'mixed_mode', 'ocean_standard', 'reroute_overland'];
            var validAllocation = ['strategic_priority', 'revenue_priority', 'balanced', 'contractual_only'];
            var validFinance = ['draw_credit', 'defer_capex', 'renegotiate_terms', 'conservative'];

            if (!validSupplier.includes(decisions.supplier)) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('invalid_supplier'), 'warning');
                return false;
            }
            if (!validLogistics.includes(decisions.logistics)) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('invalid_logistics'), 'warning');
                return false;
            }
            if (!validAllocation.includes(decisions.allocation)) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('invalid_allocation'), 'warning');
                return false;
            }
            if (!validFinance.includes(decisions.finance)) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('invalid_finance'), 'warning');
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var supEff = this.SUPPLIER_EFFECTS[d.supplier] || this.SUPPLIER_EFFECTS.moderate_diversify;
            var logEff = this.LOGISTICS_EFFECTS[d.logistics] || this.LOGISTICS_EFFECTS.mixed_mode;
            var allEff = this.ALLOCATION_EFFECTS[d.allocation] || this.ALLOCATION_EFFECTS.balanced;
            var finEff = this.FINANCE_EFFECTS[d.finance] || this.FINANCE_EFFECTS.conservative;

            var periodCost = round.baseDrain + supEff.costImpact + logEff.costImpact + finEff.costImpact;

            var portRecoveryBonus = round.portCapacity * 0.15;
            var newOtif = ds.otif + supEff.otifBoost + logEff.otifBoost + allEff.otifBoost - round.otifDrain + portRecoveryBonus * 0.3;
            newOtif = Math.max(0, Math.min(100, newOtif));

            var newRecovery = ds.recoveryLevel - round.recoveryDrain + supEff.recoveryBoost + portRecoveryBonus;
            newRecovery = Math.max(0, Math.min(100, newRecovery));

            var newSatisfaction = ds.customerSatisfaction + supEff.satBoost + logEff.satBoost + allEff.satBoost - round.satisfactionDrain;
            newSatisfaction = Math.max(0, Math.min(100, newSatisfaction));

            var newCash = ds.cash - periodCost + finEff.cashBoost + allEff.revenueImpact;

            var newCrisisCost = ds.totalCrisisCost + periodCost;

            ds.cash = Math.round(newCash);
            ds.otif = Math.round(newOtif * 10) / 10;
            ds.recoveryLevel = Math.round(newRecovery * 10) / 10;
            ds.customerSatisfaction = Math.round(newSatisfaction * 10) / 10;
            ds.totalCrisisCost = Math.round(newCrisisCost);

            ds.otifHistory.push(ds.otif);
            ds.cashHistory.push(ds.cash);
            ds.recoveryHistory.push(ds.recoveryLevel);
            ds.satisfactionHistory.push(ds.customerSatisfaction);
            ds.crisisCostHistory.push(ds.totalCrisisCost);

            var self = this;
            var gradedPeriod = state.currentPeriod;
            if (gradedPeriod < this.ROUNDS.length) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: gradedPeriod + 1 });
                }, 500);
            }

            return {
                period: state.currentPeriod,
                supplier: d.supplier,
                logistics: d.logistics,
                allocation: d.allocation,
                finance: d.finance,
                periodCost: periodCost,
                otif: ds.otif,
                cash: ds.cash,
                recoveryLevel: ds.recoveryLevel,
                customerSatisfaction: ds.customerSatisfaction,
                totalCrisisCost: ds.totalCrisisCost
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('otifDisplay', 'domainState.otif', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('recoveryDisplay', 'domainState.recoveryLevel', function(v) { return Math.round(v) + '%'; });
            uiManager.bind('satisfactionDisplay', 'domainState.customerSatisfaction', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('crisisCostDisplay', 'domainState.totalCrisisCost', function(v) { return '$' + Math.round(v).toLocaleString(); });
        }

        getChartConfig() {
            return {
                serviceChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'OTIF %',
                                data: [],
                                borderColor: '#2980b9',
                                backgroundColor: 'rgba(41,128,185,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Customer Satisfaction',
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: false } },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                },
                financialChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Cash Position ($M)',
                                data: [],
                                borderColor: '#16a085',
                                backgroundColor: 'rgba(22,160,133,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Cumulative Crisis Cost ($M)',
                                data: [],
                                borderColor: '#c0392b',
                                backgroundColor: 'rgba(192,57,43,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: false } },
                        scales: { y: { beginAtZero: true } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.otifHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                serviceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.otifHistory },
                        { data: state.domainState.satisfactionHistory }
                    ]
                },
                financialChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.cashHistory.map(function(v) { return Math.round(v / 1000000); }) },
                        { data: state.domainState.crisisCostHistory.map(function(v) { return Math.round(v / 1000000); }) }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var finalOtif = r.otif || 0;
            var finalSat = r.customerSatisfaction || 0;
            var finalCash = r.cash || 0;
            var finalRecovery = r.recoveryLevel || 0;
            var finalCost = r.totalCrisisCost || 0;

            var otifScore = (finalOtif / 100) * 30;
            var finScore = Math.min(25, (finalCash / 50000000) * 25);
            var recScore = (finalRecovery / 100) * 20;
            var satScore = (finalSat / 100) * 15;

            var balancedCount = 0;
            history.forEach(function(h) {
                var dec = h.decisions || {};
                if (dec.allocation === 'balanced' || dec.allocation === 'strategic_priority') balancedCount++;
            });
            var commScore = Math.min(10, (balancedCount / history.length) * 10);

            var totalScore = Math.round(otifScore + finScore + recScore + satScore + commScore);

            var t = function(k) { return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k; };
            var performance = t('tier_needs');
            if (totalScore >= 75) performance = t('tier_excellent');
            else if (totalScore >= 55) performance = t('tier_good');
            else if (totalScore >= 40) performance = t('tier_adequate');

            var insights = [];
            if (finalOtif > 70) insights.push(t('insight_otif_strong'));
            if (finalOtif <= 50) insights.push(t('insight_otif_weak'));
            if (finalCash > 30000000) insights.push(t('insight_cash_strong'));
            if (finalCash <= 20000000) insights.push(t('insight_cash_weak'));
            if (finalRecovery > 80) insights.push(t('insight_recovery_strong'));
            if (finalSat > 75) insights.push(t('insight_sat_strong'));

            return {
                totalScore: totalScore,
                otifScore: Math.round(otifScore),
                finScore: Math.round(finScore),
                recScore: Math.round(recScore),
                satScore: Math.round(satScore),
                commScore: Math.round(commScore),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var period = state.currentPeriod || 1;
            if (results.otif < 40) return window.mySimulation.t('hint_otif_critical');
            if (results.cash < 15000000) return window.mySimulation.t('hint_cash_critical');
            if (period <= 2 && results.otif < 70) return window.mySimulation.t('hint_early_action');
            if (period === 3) return window.mySimulation.t('hint_supplier_choice');
            if (period === 4 && results.customerSatisfaction < 60) return window.mySimulation.t('hint_customer_risk');
            if (period >= 5 && results.recoveryLevel > 70) return window.mySimulation.t('hint_stabilizing');
            if (period >= 5 && results.cash < 25000000) return window.mySimulation.t('hint_cash_pressure');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.supplier', label: 'Supplier Strategy', i18nKey: 'col_supplier', formatter: function(v) { var m = { aggressive_diversify: 'supplier_aggressive', moderate_diversify: 'supplier_moderate', maintain_current: 'supplier_maintain', cost_minimize: 'supplier_cost' }; return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(m[v] || v) : v; } },
